import{_ as n,C as t,o as s,c as i,E as a,a2 as l}from"./chunks/framework.uPk2SrVb.js";const c="/joinwell52/assets/execution-boundaries-20261028/stopped-but-tool-ran.figure.en.svg",w=JSON.parse('{"title":"The AI stopped. Why did a queued tool still start?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The AI stopped. Why did a queued tool still start?","date":"2026-10-28","published_date":"2026-10-28","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"The AI stopped. Why did a queued tool still start?","summary":"A 16-case comparison opens a larger question: when an AI says it stopped, what facts should it provide about queued work, active calls, and external effects?","cover":"/assets/execution-boundaries-20261028/stopped-but-tool-ran.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Pinned source; upstream before-and-after replay and independent synthetic remote probe","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-10-28-stopped-but-tool-ran.md","filePath":"en/research/2026-10-28-stopped-but-tool-ran.md","lastUpdated":null}'),d={name:"en/research/2026-10-28-stopped-but-tool-ran.md"};function h(p,e,u,m,g,f){const o=t("ArticleCover"),r=t("ArticleTableScroll");return s(),i("div",null,[a(o,{image:"/assets/execution-boundaries-20261028/stopped-but-tool-ran.cover-v1.png",kicker:"Open-source engineering · Controlled comparison",title:"The AI stopped. Why did a queued tool still start?",summary:"A 16-case comparison opens a larger question: when an AI says it stopped, what facts should it provide about queued work, active calls, and external effects?",version:"2026-10-28",languageHref:"/zh/research/2026-10-28-stopped-but-tool-ran",languageLabel:"中文"}),a(r,{language:"en"}),e[0]||(e[0]=l('<h1 id="the-ai-stopped-why-did-a-queued-tool-still-start" tabindex="-1">The AI stopped. Why did a queued tool still start? <a class="header-anchor" href="#the-ai-stopped-why-did-a-queued-tool-still-start" aria-label="Permalink to &quot;The AI stopped. Why did a queued tool still start?&quot;">​</a></h1><p>Imagine asking an AI assistant to inspect some material, organize files, and then take an action. A check fails during the first step. The assistant reports that the task has failed and execution has stopped.</p><p>That sounds reassuring. But a second tool may already be running, while a third is waiting in a queue. <strong>Reporting a failure</strong> and <strong>preventing the next action</strong> are different events. For an agent that can call external tools, the time between them matters more than the final message.</p><p>The deeper question in this article is: <strong>what evidence would make “stopped” a trustworthy claim?</strong> One status label cannot describe queued work, in-flight calls, and operations already sent to an outside system. We first test the execution queue, then place that result in the larger engineering problem.</p><h2 id="why-we-followed-this-change" tabindex="-1">Why we followed this change <a class="header-anchor" href="#why-we-followed-this-change" aria-label="Permalink to &quot;Why we followed this change&quot;">​</a></h2><p>Among the <a href="https://joinwell52-ai.github.io/joinwell52/en/runtime/daily-intelligence/2026-10-28" target="_blank" rel="noreferrer">18 engineering developments we collected on October 28</a>, <a href="https://github.com/openai/openai-agents-python/pull/5446" target="_blank" rel="noreferrer">OpenAI Agents Python PR #5446</a> describes a precise gap. A function-tool failure had already been selected as the run&#39;s error. While previously completed output was being finalized, a queued native tool could still proceed. A parallel input guardrail rejection created a related stopping boundary.</p><p>Our question was: <strong>When does “stop” actually reach the execution queue?</strong> Pinned code on both sides of the fix and a common test make that question testable.</p><h2 id="separating-reported-error-from-stopped-action" tabindex="-1">Separating “reported error” from “stopped action” <a class="header-anchor" href="#separating-reported-error-from-stopped-action" aria-label="Permalink to &quot;Separating “reported error” from “stopped action”&quot;">​</a></h2><p>We did not call a real model or let tools change real files or network resources. The upstream regression test uses a <code>ScriptedModel</code> to emit a known sequence of tool calls. Synthetic custom and local shell tools record whether they start and receive cancellation. The test controls the moment when one tool is active, another is queued, and a function failure is selected.</p><p>We ran the same test against the pre-fix commit <a href="https://github.com/openai/openai-agents-python/tree/a91f0bfe013a63ce0ad8935c8c2d25047d249002" target="_blank" rel="noreferrer"><code>a91f0bfe</code></a> and merge commit <a href="https://github.com/openai/openai-agents-python/tree/cd26bbbc52847845fde73b9952b51e62e2bcbdc0" target="_blank" rel="noreferrer"><code>cd26bbbc</code></a>. It combines two tool kinds, streaming or non-streaming, rejected or accepted input, and cleanup with or without an error: 16 controlled schedules.</p><table tabindex="0"><thead><tr><th>Source</th><th>Result across 16 schedules</th><th>What the result means</th></tr></thead><tbody><tr><td>Before the fix</td><td><strong>16/16 failed</strong></td><td>The active native tool did not receive the expected cancellation during this window.</td></tr><tr><td>Merge commit</td><td><strong>16/16 passed</strong></td><td>In the same schedules, the active tool was cancelled and the queued call stayed behind the stopping boundary.</td></tr></tbody></table><p>We also ran both related test files at the merge commit: <strong>84/84 passed</strong>. This does not mean 84 real-world situations are safe; it means those regression checks passed. All 16 pre-fix failures reached the same cancellation assertion. We printed the module path to verify that the old-source run actually loaded the old source.</p><h2 id="a-second-counterexample-a-remote-outcome-can-outlive-cancellation" tabindex="-1">A second counterexample: a remote outcome can outlive cancellation <a class="header-anchor" href="#a-second-counterexample-a-remote-outcome-can-outlive-cancellation" aria-label="Permalink to &quot;A second counterexample: a remote outcome can outlive cancellation&quot;">​</a></h2><p>That comparison answers whether a queued call starts. It does not answer what happens to an action already handed to an external system. We built a separate probe through the merge commit&#39;s real <code>Runner</code> and tool entry point. An active tool gives a request to a <strong>synthetic delayed remote worker</strong> before a function failure is selected. The worker is a separately scheduled task in the same process, not a network service.</p><p>At the failure point, the active tool had received cancellation and the queued call had not started. Yet the worker had accepted the request. We released it only after the local run ended, and it still committed. This did not uncover a new OpenAI SDK bug. It establishes a narrower boundary: <strong>a local stop status cannot answer for the final outcome of a request already accepted elsewhere.</strong> The <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-10-28-execution-boundaries" target="_blank" rel="noreferrer">probe and two state snapshots</a> are public.</p><p><img src="'+c+'" alt="A selected function failure cancels an active tool and keeps a queued call behind the boundary"></p><p><em>Figure: the controlled schedule we tested. It does not imply rollback of a tool action already completed elsewhere.</em></p><h2 id="from-cancellation-to-a-checkable-stop-record" tabindex="-1">From cancellation to a checkable stop record <a class="header-anchor" href="#from-cancellation-to-a-checkable-stop-record" aria-label="Permalink to &quot;From cancellation to a checkable stop record&quot;">​</a></h2><p>The fix makes a selected failure visible to other tool execution: active native tools receive cancellation, and their queue stops releasing new calls. It still gives already completed output a bounded finalization window. A cancellation requested by the caller takes priority.</p><p>The direct observation is that, in these controlled schedules, a selected failure no longer leaves the active and queued native work on the old path. A more complete stop record needs to answer three separate questions:</p><ol><li><strong>Was the queue closed?</strong> Could a late message, retry, or next tool call restart work? The <a href="https://github.com/openai/codex/releases/tag/rust-v0.165.0" target="_blank" rel="noreferrer">Codex 0.165.0 release notes</a> describe a fix for queued agent messages restarting work after an interrupt. That is an upstream release fact from another project, not something we retested here.</li><li><strong>Where did the active call end?</strong> Cancelling a Python task need not mean its underlying executor has stopped. The <a href="https://github.com/ag2ai/ag2/releases/tag/v1.2.2" target="_blank" rel="noreferrer">AG2 1.2.2 release notes</a> explicitly caution that a synchronous tool worker may keep running after a timeout and may have side effects. Our synthetic tools observed cancellation signals; they cannot stand in for a real worker.</li><li><strong>Was the external outcome resolved?</strong> The synthetic probe shows that an accepted request may commit after local cancellation. <a href="https://github.com/paperclipai/paperclip/pull/17439" target="_blank" rel="noreferrer">Paperclip&#39;s handover implementation</a> pauses uncertain mutations for later verification. It offers a useful comparison; we did not run Paperclip&#39;s handover path.</li></ol><p>These three questions are an <strong>engineering judgment drawn from our two bounded probes and three separately sourced changes</strong>. They are not a protocol validated against a real network service. Cancellation itself does not reverse an external effect. PR #5446 was merged; we did not verify its inclusion in a specific package release.</p><p>A minimal stop record worth discussing would distinguish calls that never started, calls that received cancellation but have not confirmed completion, and calls whose external outcome remains unknown. Each needs a time and tool identity. A resumed agent could then see which work needs no replay and which external state must be checked first. We have not implemented or tested this record format.</p><p>If an agent handles real work for you, a concrete question is: after a failed check or a stop request, can it tell you which calls never started, which had already started, and which may still have an uncertain external outcome?</p><p>A next experiment should replace the synthetic worker with an independently queryable service and inspect the record given to a resumed agent. This probe did not test recovery. Engineers can debate who should reconcile the uncertain outcome: the tool, the runtime, or the application. Users may recognize the symptom too: a task says it stopped, yet a file or remote state changes later. The event sequence is more informative than the label.</p><p>See the <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-10-28-execution-boundaries/00-report.en.md" target="_blank" rel="noreferrer">public experiment report</a> for pinned versions, independent probe, commands, and limits. This round combines a local before-and-after replay with a synthetic counterexample, not a production incident reproduction. <a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">Research repository</a></p>',26))])}const y=n(d,[["render",h]]);export{w as __pageData,y as default};
